static int load_wavefront_obj(const char *modelname, WAVEFRONT_MODEL_T *model, struct wavefront_model_loading_s *m)
{
   char line[256+1];
   unsigned short pp[54+1];
   FILE *fp;
   int i, valid;
   float *qv = (float *)m->data;
   float *qt = (float *)m->data + 3 * MAX_VERTICES;
   float *qn = (float *)m->data + (3+2) * MAX_VERTICES;
   unsigned short *qf = (unsigned short *)((float *)m->data + (3+2+3) * MAX_VERTICES);
   float *pv = qv, *pt = qt, *pn = qn;
   unsigned short *pf = qf;
   fp = fopen(modelname, "r");
   if (!fp) return -1;

   m->num_materials = 0;
   m->material_index[0] = 0;

   valid = fread(line, 1, sizeof(line)-1, fp);

   while (valid > 0) {
      char *s, *end = line;

      while((end-line < valid) && *end != '\n' && *end != '\r')
         end++;
      *end++ = 0;

      if((end-line < valid) && *end != '\n' && *end != '\r')
         *end++ = 0;

      s = line;

      if (s[strlen(s)-1] == 10) s[strlen(s)-1]=0;
      switch (s[0]) {
      case '#': break; // comment
      case '\r': case '\n': case '\0': break; // blank line
      case 'm': vc_assert(strncmp(s, "mtllib", sizeof "mtllib"-1)==0); break;
      case 'o': break;
      case 'u': 
         if (sscanf(s, "usemtl %s", /*MAX_MATERIAL_NAME-1, */model->material[m->num_materials].name) == 1) {
            if (m->num_materials < MAX_MATERIALS) {
               if (m->num_materials > 0 && ((pf-qf)/3 == m->material_index[m->num_materials-1] || strcmp(model->material[m->num_materials-1].name, model->material[m->num_materials].name)==0)) {
                  strcpy(model->material[m->num_materials-1].name, model->material[m->num_materials].name);
                  m->num_materials--;
               } else
               m->material_index[m->num_materials] = (pf-qf)/3;
               m->num_materials++;
            }
         } else { printf(s); vc_assert(0); }
         break;
      case 'g': vc_assert(strncmp(s, "g ", sizeof "g "-1)==0); break;
      case 's': vc_assert(strncmp(s, "s ", sizeof "s "-1)==0); break;
      case 'v': case 'f':
         if (sscanf(s, "v %f %f %f", pv+0, pv+1, pv+2) == 3) {
            pv += 3;
         } else if (sscanf(s, "vt %f %f", pt+0, pt+1) == 2) {
            pt += 2;
         } else if (sscanf(s, "vn %f %f %f", pn+0, pn+1, pn+2) == 3) {
            pn += 3;
         } else if (i = sscanf(s, "f"" %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu"
                                     " %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu"
                                     " %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu//%hu %hu",
               pp+ 0, pp+ 1, pp+ 2, pp+ 3, pp+ 4, pp+ 5, pp+ 6, pp+ 7, pp+ 8, pp+ 9, pp+10, pp+11, 
               pp+12, pp+13, pp+14, pp+15, pp+16, pp+17, pp+18, pp+19, pp+20, pp+21, pp+22, pp+23, 
               pp+24, pp+25, pp+26, pp+27, pp+28, pp+29, pp+30, pp+32, pp+32, pp+33, pp+34, pp+35, pp+36), i >= 6) {
            int poly = i/2;
            //vc_assert(i < countof(pp)); // may need to increment poly count and pp array
            for (i=1; i<poly-1; i++) {
               *pf++ = pp[0]; *pf++ = 0; *pf++ = pp[1];
               *pf++ = pp[2*i+0]; *pf++ = 0; *pf++ = pp[2*i+1];
               *pf++ = pp[2*(i+1)+0]; *pf++ = 0; *pf++ = pp[2*(i+1)+1];
            }
         } else if (i = sscanf(s, "f"" %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu"
                                     " %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu"
                                     " %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu/%hu %hu",
               pp+ 0, pp+ 1, pp+ 2, pp+ 3, pp+ 4, pp+ 5, pp+ 6, pp+ 7, pp+ 8, pp+ 9, pp+10, pp+11, 
               pp+12, pp+13, pp+14, pp+15, pp+16, pp+17, pp+18, pp+19, pp+20, pp+21, pp+22, pp+23, 
               pp+24, pp+25, pp+26, pp+27, pp+28, pp+29, pp+30, pp+32, pp+32, pp+33, pp+34, pp+35, pp+36), i >= 6) {
            int poly = i/2;
            //vc_assert(i < countof(pp); // may need to increment poly count and pp array
            for (i=1; i<poly-1; i++) {
               *pf++ = pp[0]; *pf++ = pp[1]; *pf++ = 0;
               *pf++ = pp[2*i+0]; *pf++ = pp[2*i+1]; *pf++ = 0;
               *pf++ = pp[2*(i+1)+0]; *pf++ = pp[2*(i+1)+1]; *pf++ = 0;
            }
         } else if (i = sscanf(s, "f"" %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu"
                                     " %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu"
                                     " %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu/%hu/%hu %hu",
               pp+ 0, pp+ 1, pp+ 2, pp+ 3, pp+ 4, pp+ 5, pp+ 6, pp+ 7, pp+ 8, pp+ 9, pp+10, pp+11, pp+12, pp+13, pp+14, pp+15, pp+16, pp+17, 
               pp+18, pp+19, pp+20, pp+21, pp+22, pp+23, pp+24, pp+25, pp+26, pp+27, pp+28, pp+29, pp+30, pp+32, pp+32, pp+33, pp+34, pp+35, 
               pp+36, pp+37, pp+38, pp+39, pp+40, pp+41, pp+42, pp+43, pp+44, pp+45, pp+46, pp+47, pp+48, pp+49, pp+50, pp+51, pp+52, pp+53, pp+54), i >= 9) {
            int poly = i/3;
            //vc_assert(i < countof(pp); // may need to increment poly count and pp array
            for (i=1; i<poly-1; i++) {
               *pf++ = pp[0]; *pf++ = pp[1]; *pf++ = pp[2];
               *pf++ = pp[3*i+0]; *pf++ = pp[3*i+1]; *pf++ = pp[3*i+2];
               *pf++ = pp[3*(i+1)+0]; *pf++ = pp[3*(i+1)+1]; *pf++ = pp[3*(i+1)+2];
            }
         } else { printf(s); vc_assert(0); }
         break;
      default: 
         printf("%02x %02x %s", s[0], s[1], s); vc_assert(0); break;
      }

      // shift down read characters and read some more into the end
      // if we didn't find a newline, then end is one off the end of our
      // line, so end-line will be valid+1
      i = end-line > valid ? valid : end-line;
      memmove(line, end, valid - i);
      valid -= i;
      valid += fread(line+valid, 1, sizeof(line)-1-valid, fp);
   }
   fclose(fp);

   if (m->num_materials==0) m->material_index[m->num_materials++] = 0;

   centre_and_rescale(qv, (pv-qv)/3);
   renormalise(qn, (pn-qn)/3);
   //centre_and_rescale2(qt, (pt-qt)/2);

   m->numv = pv-qv;
   m->numt = pt-qt;
   m->numn = pn-qn;
   m->numf = pf-qf;

   // compress array
   //memcpy((float *)m->data, (float *)m->data, m->numv * sizeof *qv); - nop
   memcpy((float *)m->data + m->numv, (float *)m->data + 3 * MAX_VERTICES, m->numt * sizeof *qt);
   memcpy((float *)m->data + m->numv + m->numt,(float *) m->data + (3 + 2) * MAX_VERTICES, m->numn * sizeof *qn);
   memcpy((float *)m->data + m->numv + m->numt + m->numn, (float *)m->data + (3 + 2 + 3) * MAX_VERTICES, m->numf * sizeof *qf);

   return 0;
}

348: static int parse_cmdline(int argc, const char **argv, RASPIVIDYUV_STATE *state)
349: {
350:    // Parse the command line arguments.
351:    // We are looking for --<something> or -<abbreviation of something>
352: 
353:    int valid = 1;
354:    int i;
355: 
356:    for (i = 1; i < argc && valid; i++)
357:    {
358:       int command_id, num_parameters;
359: 
360:       if (!argv[i])
361:          continue;
362: 
363:       if (argv[i][0] != '-')
364:       {
365:          valid = 0;
366:          continue;
367:       }
368: 
369:       // Assume parameter is valid until proven otherwise
370:       valid = 1;
371: 
372:       command_id = raspicli_get_command_id(cmdline_commands, cmdline_commands_size, &argv[i][1], &num_parameters);
373: 
374:       // If we found a command but are missing a parameter, continue (and we will drop out of the loop)
375:       if (command_id != -1 && num_parameters > 0 && (i + 1 >= argc) )
376:          continue;
377: 
378:       //  We are now dealing with a command line option
379:       switch (command_id)
380:       {
381:       case CommandTimeout: // Time to run viewfinder/capture
382:       {
383:          if (sscanf(argv[i + 1], "%d", &state->timeout) == 1)
384:          {
385:             // Ensure that if previously selected a waitMethod we don't overwrite it
386:             if (state->timeout == 0 && state->waitMethod == WAIT_METHOD_NONE)
387:                state->waitMethod = WAIT_METHOD_FOREVER;
388: 
389:             i++;
390:          }
391:          else
392:             valid = 0;
393:          break;
394:       }
395: 
396:       case CommandDemoMode: // Run in demo mode - no capture
397:       {
398:          // Demo mode might have a timing parameter
399:          // so check if a) we have another parameter, b) its not the start of the next option
400:          if (i + 1 < argc  && argv[i+1][0] != '-')
401:          {
402:             if (sscanf(argv[i + 1], "%u", &state->demoInterval) == 1)
403:             {
404:                // TODO : What limits do we need for timeout?
405:                if (state->demoInterval == 0)
406:                   state->demoInterval = 250; // ms
407: 
408:                state->demoMode = 1;
409:                i++;
410:             }
411:             else
412:                valid = 0;
413:          }
414:          else
415:          {
416:             state->demoMode = 1;
417:          }
418: 
419:          break;
420:       }
421: 
422:       case CommandFramerate: // fps to record
423:       {
424:          if (sscanf(argv[i + 1], "%u", &state->framerate) == 1)
425:          {
426:             // TODO : What limits do we need for fps 1 - 30 - 120??
427:             i++;
428:          }
429:          else
430:             valid = 0;
431:          break;
432:       }
433: 
434:       case CommandTimed:
435:       {
436:          if (sscanf(argv[i + 1], "%u,%u", &state->onTime, &state->offTime) == 2)
437:          {
438:             i++;
439: 
440:             if (state->onTime < 1000)
441:                state->onTime = 1000;
442: 
443:             if (state->offTime < 1000)
444:                state->offTime = 1000;
445: 
446:             state->waitMethod = WAIT_METHOD_TIMED;
447: 
448:             if (state->timeout == -1)
449:                state->timeout = 0;
450:          }
451:          else
452:             valid = 0;
453:          break;
454:       }
455: 
456:       case CommandKeypress:
457:          state->waitMethod = WAIT_METHOD_KEYPRESS;
458: 
459:          if (state->timeout == -1)
460:             state->timeout = 0;
461: 
462:          break;
463: 
464:       case CommandSignal:
465:          state->waitMethod = WAIT_METHOD_SIGNAL;
466:          // Reenable the signal
467:          signal(SIGUSR1, default_signal_handler);
468: 
469:          if (state->timeout == -1)
470:             state->timeout = 0;
471: 
472:          break;
473: 
474:       case CommandInitialState:
475:       {
476:          state->bCapturing = raspicli_map_xref(argv[i + 1], initial_map, initial_map_size);
477: 
478:          if( state->bCapturing == -1)
479:             state->bCapturing = 0;
480: 
481:          i++;
482:          break;
483:       }
484: 
485:       case CommandOnlyLuma:
486:          if (state->useRGB)
487:          {
488:             fprintf(stderr, "--luma and --rgb are mutually exclusive\n");
489:             valid = 0;
490:          }
491:          state->onlyLuma = 1;
492:          break;
493: 
494:       case CommandUseRGB: // display lots of data during run
495:          if (state->onlyLuma)
496:          {
497:             fprintf(stderr, "--luma and --rgb are mutually exclusive\n");
498:             valid = 0;
499:          }
500:          state->useRGB = 1;
501:          break;
502: 
503:       case CommandSavePTS:  // output filename
504:       {
505:          state->save_pts = 1;
506:          int len = strlen(argv[i + 1]);
507:          if (len)
508:          {
509:             state->pts_filename = malloc(len + 1);
510:             vcos_assert(state->pts_filename);
511:             if (state->pts_filename)
512:                strncpy(state->pts_filename, argv[i + 1], len+1);
513:             i++;
514:          }
515:          else
516:             valid = 0;
517:          break;
518:       }
519: 
520:       case CommandNetListen:
521:       {
522:          state->netListen = true;
523: 
524:          break;
525:       }
526: 
527:       default:
528:       {
529:          // Try parsing for any image specific parameters
530:          // result indicates how many parameters were used up, 0,1,2
531:          // but we adjust by -1 as we have used one already
532:          const char *second_arg = (i + 1 < argc) ? argv[i + 1] : NULL;
533:          int parms_used = (raspicamcontrol_parse_cmdline(&state->camera_parameters, &argv[i][1], second_arg));
534: 
535:          // Still unused, try common settings
536:          if (!parms_used)
537:             parms_used = raspicommonsettings_parse_cmdline(&state->common_settings, &argv[i][1], second_arg, &application_help_message);
538: 
539:          // Still unused, try preview options
540:          if (!parms_used)
541:             parms_used = raspipreview_parse_cmdline(&state->preview_parameters, &argv[i][1], second_arg);
542: 
543:          // If no parms were used, this must be a bad parameters
544:          if (!parms_used)
545:             valid = 0;
546:          else
547:             i += parms_used - 1;
548: 
549:          break;
550:       }
551:       }
552:    }
553: 
554:    if (!valid)
555:    {
556:       fprintf(stderr, "Invalid command line option (%s)\n", argv[i-1]);
557:       return 1;
558:    }
559: 
560:    return 0;
561: }

static int load_wavefront_obj(const char *modelname, WAVEFRONT_MODEL_T *model, struct wavefront_model_loading_s *m)
{
