577:    // If invalid command, or we are missing a parameter, drop out
578:    if (command_id==-1 || (command_id != -1 && num_parameters > 0 && arg2 == NULL))
579:       return 0;
580: 
581:    switch (command_id)
582:    {
583:    case CommandSharpness : // sharpness - needs single number parameter
584:       sscanf(arg2, "%d", &params->sharpness);
585:       used = 2;
586:       break;
587: 
588:    case CommandContrast : // contrast - needs single number parameter
