596:       break;
597: 
598:    case CommandSaturation : // saturation - needs single number parameter
599:       sscanf(arg2, "%d", &params->saturation);
600:       used = 2;
601:       break;
602: 
603:    case CommandISO : // ISO - needs single number parameter
604:       sscanf(arg2, "%d", &params->ISO);
605:       used = 2;
606:       break;
607: 
608:    case CommandVideoStab : // video stabilisation - if here, its on
