int main_mbox(int argc, char *argv[])
{
  int mb = mbox_open();
  int i;
  char command[MAX_STRING] = {};
  char result[MAX_STRING] = {};

  for (i = 1; i < argc; i++)
  {
    char *c = command + strlen(command);
    if (c > command)
    {
       strncat(c, " ", command + sizeof command - c);
       c = command + strlen(command);
    }
    strncat(c, argv[i], command + sizeof command - c);
  }

  int ret = gencmd(mb, command, result, sizeof result);
  if (ret)
    printf( "vc_gencmd_read_response returned %d\n", ret );

  mbox_close(mb);

  printf("%s\n", result);
  return ret;
}

char *read_file_as_string(const char *path, int *plen)
{
    FILE *fp = fopen(path, "r");
    char *string = NULL;
    long len = 0;
    if (fp)
    {
        long bytes_read;

        fseek(fp, 0, SEEK_END);
        len = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        /* Ensure NUL-termination */
        string = malloc(len + 1);
        if (!string)
            fatal_error("Out of memory", path);
        string[len] = 0;
        bytes_read = fread(string, 1, len, fp);
        if (bytes_read != len)
            fatal_error("Failed to read file '%s'", path);
        fclose(fp);
    }
    if (plen)
        *plen = (int)len;
    return string;
}

