394:                   msg->drvbuf.client_context->callback(msg);
395:                }
396:                else
397:                {
398:                   /* impossible short data length */
399:                   LOG_ERROR("Message with invalid short payload length %d",
400:                             msg->payload_in_message);
401:                   vcos_assert(0);
402:                }
403:             }
404:             else
405:             {
406: 
407:                /* Message received from videocore; the client_context should have
408:                 * been passed all the way through by videocore back to us, and will
409:                 * be picked up in the callback to complete the sequence.
410:                 */
411:                LOG_TRACE("doing cb (%p) context %p",
412:                          msg->drvbuf.client_context, msg->drvbuf.client_context ?
413:                          msg->drvbuf.client_context->callback : 0);
414:                msg->drvbuf.client_context->callback(msg);
415:                LOG_TRACE("done callback back to client");
416:                vchiq_release_message(service, vchiq_header);
417:             }
418:          }
419:          else if (msg->msgid == MMAL_WORKER_EVENT_TO_HOST)
420:          {
421:             mmal_vc_handle_event_msg(vchiq_header, service, context);
422:          }
423:          else
424:          {
425:             MMAL_WAITER_T *waiter = msg->u.waiter;
426:             LOG_TRACE("waking up waiter at %p", waiter);
427:             vcos_assert(waiter->inuse);
428:             int len = vcos_min(waiter->destlen, vchiq_header->size);
429:             waiter->destlen = len;
430:             LOG_TRACE("copying payload @%p to %p len %d", waiter->dest, msg, len);
431:             memcpy(waiter->dest, msg, len);
432:             vchiq_release_message(service, vchiq_header);
433:             vcos_semaphore_post(&waiter->sem);
434:          }
435:       }
436:       break;
437:    case VCHIQ_BULK_TRANSMIT_DONE:
438:       {
439:          /* nothing to do here, need to wait for the copro to tell us it
440:           * has emptied the buffer before we can recycle it, otherwise we
441:           * end up feeding the copro with buffers it cannot handle.
442:           */
443: #ifdef VCOS_LOGGING_ENABLED
444:          mmal_worker_buffer_from_host *msg = (mmal_worker_buffer_from_host *)context;
445: #endif
446:          LOG_TRACE("bulk tx done: %p, %d", msg->buffer_header.data, msg->buffer_header.length);
447:       }
448:       break;
449:    case VCHIQ_BULK_RECEIVE_DONE:
450:       {
451:          VCHIQ_HEADER_T *header = (VCHIQ_HEADER_T *)context;
452:          mmal_worker_msg_header *msg_hdr = (mmal_worker_msg_header*)header->data;
453:          if (msg_hdr->msgid == MMAL_WORKER_BUFFER_TO_HOST)
454:          {
455:             mmal_worker_buffer_from_host *msg = (mmal_worker_buffer_from_host *)msg_hdr;
